6	import { sha256 } from './crypto'
7	
8	export const equal = (a: ArrayBuffer, b: ArrayBuffer): boolean => {
9	  if (a === b) {
10	    return true
11	  }
12	  if (a.byteLength !== b.byteLength) {
13	    return false
14	  }
15	
16	  const va = new DataView(a)
17	  const vb = new DataView(b)
18	
19	  let i = va.byteLength
20	  while (i--) {
21	    if (va.getUint8(i) !== vb.getUint8(i)) {
22	      return false
23	    }
24	  }
25	
26	  return true
27	}
28	
29	const constantTimeEqualString = (a: string, b: string): boolean => {
30	  const aLen = a.length
31	  const bLen = b.length
32	  const maxLen = Math.max(aLen, bLen)
33	  let out = aLen ^ bLen
34	  for (let i = 0; i < maxLen; i++) {
35	    const aChar = i < aLen ? a.charCodeAt(i) : 0
36	    const bChar = i < bLen ? b.charCodeAt(i) : 0
37	    out |= aChar ^ bChar
38	  }
39	  return out === 0
40	}
