import { Hono } from '__SRC__/hono'
import { csrf } from '__SRC__/middleware/csrf'
import { parseBody } from '__SRC__/utils/body'
import { HonoRequest } from '__SRC__/request'

const show = async (label: string, fn: () => Promise<unknown>) => {
  try {
    console.log(label, '=>', JSON.stringify(await fn()))
  } catch (e) {
    console.log(label, '=> THROW', (e as Error).name, (e as Error).message)
  }
}

const mk = (body: BodyInit, ct?: string) =>
  new Request('http://localhost/x', {
    method: 'POST',
    body,
    headers: ct ? { 'Content-Type': ct } : {},
  })

// A. formData() first, then parseBody() -- urlencoded
await show('A1 urlencoded formData->parseBody', async () => {
  const r = new HonoRequest(mk('a=x%26admin%3Dtrue%26z%3D', 'application/x-www-form-urlencoded'))
  const fd = await r.formData()
  const first = Object.fromEntries(fd.entries())
  const second = await r.parseBody()
  return { first, second }
})

// A2. multipart formData() first, then parseBody()
await show('A2 multipart formData->parseBody', async () => {
  const f = new FormData()
  f.append('a', 'b')
  const r = new HonoRequest(mk(f))
  const fd = await r.formData()
  const first = Object.fromEntries(fd.entries())
  const second = await r.parseBody()
  return { first, second }
})

// A3. parseBody twice
await show('A3 parseBody twice', async () => {
  const r = new HonoRequest(mk('a=1&b=2', 'application/x-www-form-urlencoded'))
  return [await r.parseBody(), await r.parseBody()]
})

// A4. text() then parseBody
await show('A4 text->parseBody', async () => {
  const r = new HonoRequest(mk('a=1&b=2', 'application/x-www-form-urlencoded'))
  await r.text()
  return await r.parseBody()
})

// A5. parseBody then formData
await show('A5 parseBody->formData', async () => {
  const r = new HonoRequest(mk('a=1&b=2', 'application/x-www-form-urlencoded'))
  const p = await r.parseBody()
  const fd = await r.formData()
  return { p, fd: Object.fromEntries(fd.entries()) }
})

// B. odd content types: what does parseBody return vs what csrf decides
const cts = [
  'Application/X-WWW-Form-Urlencoded',
  ' application/x-www-form-urlencoded',
  '\x0capplication/x-www-form-urlencoded',
  'application/x-www-form-urlencoded ',
  'application/x-www-form-urlencoded \x0c; charset=utf-8',
  'application/x-www-form-urlencodedx',
  'multipart/form-data-x; boundary=abc',
  'APPLICATION/X-WWW-FORM-URLENCODED ; charset=utf-8',
]
for (const ct of cts) {
  await show(`B parseBody raw ct=${JSON.stringify(ct)}`, async () => {
    let req: Request
    try {
      req = mk('a=1&admin=true', ct)
    } catch (e) {
      return 'HEADER REJECTED: ' + (e as Error).message
    }
    const stored = req.headers.get('content-type')
    const app = new Hono()
    app.use(csrf({ origin: 'http://localhost' }))
    app.post('/x', async (c) => c.json(await c.req.parseBody()))
    const req2 = new Request(req, { headers: { 'Content-Type': ct, Origin: 'http://evil.example' } })
    const res = await app.request(req2)
    return { stored, csrfStatus: res.status, body: await res.text(), direct: await parseBody(req) }
  })
}

import { HonoRequest, cloneRawRequest } from '/home/jack/.t3/bench-runs/2026-10-10-last-push-claude-ce-opus/att-007/clone/src/request'
import { parseBody as headParseBody } from '/home/jack/.t3/bench-runs/2026-10-10-last-push-claude-ce-opus/att-007/clone/src/utils/body'
import { parseBody as baseParseBody } from './body_base'

const show = async (label: string, fn: () => Promise<unknown>) => {
  try {
    const v = await fn()
    console.log(`${label} => OK ${JSON.stringify(v)}`)
  } catch (e) {
    console.log(`${label} => THROW ${(e as Error).name}: ${(e as Error).message}`)
  }
}

const fdObj = (fd: FormData) => {
  const o: Record<string, unknown> = {}
  fd.forEach((v, k) => (o[k] = typeof v === 'string' ? v : `File(${v.name})`))
  return o
}

const multipartReq = () => {
  const data = new FormData()
  data.append('message', 'hello')
  return new Request('http://localhost/', { method: 'POST', body: data })
}
const urlencodedReq = () =>
  new Request('http://localhost/', {
    method: 'POST',
    body: new URLSearchParams({ message: 'hello' }),
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  })

const mixedMultipart = async () => {
  const src = multipartReq()
  const ct = src.headers.get('Content-Type')!.replace('multipart/form-data', 'Multipart/Form-Data')
  return new Request('http://localhost/', {
    method: 'POST',
    body: await src.arrayBuffer(),
    headers: { 'Content-Type': ct },
  })
}

console.log('--- 1. native runtime handling of mixed-case media types (no hono normalization)')
await show('native Response.formData Multipart/Form-Data', async () => {
  const body =
    '--sampleBoundary\r\nContent-Disposition: form-data; name="test"\r\n\r\nHello\r\n--sampleBoundary--'
  const r = new Response(new TextEncoder().encode(body).buffer, {
    headers: { 'Content-Type': 'Multipart/Form-Data; boundary=sampleBoundary' },
  })
  return fdObj(await r.formData())
})
await show('native Request.formData Multipart/Form-Data', async () =>
  fdObj(await (await mixedMultipart()).formData())
)
await show('native Request.formData Application/X-WWW-Form-Urlencoded', async () => {
  const r = new Request('http://localhost/', {
    method: 'POST',
    body: 'message=hello',
    headers: { 'Content-Type': 'Application/X-WWW-Form-Urlencoded' },
  })
  return fdObj(await r.formData())
})

for (const [name, parse] of [
  ['BASE', baseParseBody],
  ['HEAD', headParseBody],
] as const) {
  console.log(`--- ${name}`)
  for (const [kind, mk] of [
    ['multipart', multipartReq],
    ['urlencoded', urlencodedReq],
  ] as const) {
    await show(`${name} ${kind}: formData() then parseBody()`, async () => {
      const req = new HonoRequest(mk())
      const fd = fdObj(await req.formData())
      return { fd, parsed: await parse(req) }
    })
    await show(`${name} ${kind}: parseBody() then formData()`, async () => {
      const req = new HonoRequest(mk())
      const parsed = await parse(req)
      return { parsed, fd: fdObj(await req.formData()), keys: Object.keys(req.bodyCache) }
    })
    await show(`${name} ${kind}: parseBody() twice`, async () => {
      const req = new HonoRequest(mk())
      return [await parse(req), await parse(req)]
    })
    await show(`${name} ${kind}: text() then parseBody()`, async () => {
      const req = new HonoRequest(mk())
      await req.text()
      return await parse(req)
    })
    await show(`${name} ${kind}: blob() then parseBody()`, async () => {
      const req = new HonoRequest(mk())
      await req.blob()
      return await parse(req)
    })
    await show(`${name} ${kind}: parseBody() then text() equals original body`, async () => {
      const original = await mk().text()
      const req = new HonoRequest(mk())
      await parse(req)
      const t = await req.text()
      // boundaries differ between two FormData serializations, so compare shape loosely
      return { sameLength: t.length === original.length, startsWithDashes: t.startsWith('--'), text: kind === 'urlencoded' ? t.slice(0, 60) : undefined }
    })
    await show(`${name} ${kind}: parseBody() then cloneRawRequest().formData()`, async () => {
      const req = new HonoRequest(mk())
      await parse(req)
      const cloned = await cloneRawRequest(req)
      return { ct: cloned.headers.get('content-type')?.slice(0, 40), fd: fdObj(await cloned.formData()) }
    })
  }
  await show(`${name} malformed multipart via HonoRequest`, async () => {
    const req = new HonoRequest(
      new Request('http://localhost/', {
        method: 'POST',
        body: 'not multipart at all',
        headers: { 'Content-Type': 'multipart/form-data; boundary=abc' },
      })
    )
    return await parse(req)
  })
  await show(`${name} media type with space before ';'`, async () => {
    const req = new Request('http://localhost/', {
      method: 'POST',
      body: 'message=hello',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded ; charset=UTF-8' },
    })
    return await parse(req)
  })
  await show(`${name} mixed-case multipart raw Request`, async () => parse(await mixedMultipart()))
  await show(`${name} mixed-case multipart HonoRequest`, async () =>
    parse(new HonoRequest(await mixedMultipart()))
  )
}

export async function run(label: string, mod: { Hono: any; validator: any; parseBody: any }) {
  const { Hono, validator, parseBody } = mod
  const out: Record<string, unknown> = {}
  const safe = async (name: string, fn: () => Promise<unknown>) => {
    try {
      out[name] = await fn()
    } catch (e) {
      out[name] = 'THROW: ' + (e instanceof Error ? `${e.name}: ${e.message}` : String(e))
    }
  }
  const mkMultipart = () => {
    const fd = new FormData()
    fd.append('foo', 'bar')
    fd.append('n', '1')
    return { method: 'POST', body: fd }
  }
  const mkUrlenc = () => ({
    method: 'POST',
    body: new URLSearchParams({ foo: 'bar', n: '1' }),
  })
  const app = new Hono()
  app.onError((e: Error, c: any) => c.json({ error: `${e.name}: ${e.message}` }, 500))
  app.post('/fd-then-parse', async (c: any) => {
    const fd = await c.req.formData()
    const first = Object.fromEntries(fd.entries())
    const parsed = await c.req.parseBody()
    return c.json({ first, parsed })
  })
  app.post('/parse-twice', async (c: any) => {
    const a = await c.req.parseBody()
    const b = await c.req.parseBody()
    return c.json({ a, b })
  })
  app.post('/parse-then-fd', async (c: any) => {
    const a = await c.req.parseBody()
    const fd = await c.req.formData()
    const t = await c.req.text()
    return c.json({
      a,
      fd: Object.fromEntries(fd.entries()),
      textHasFoo: t.includes('foo'),
      keys: Object.keys(c.req.bodyCache),
    })
  })
  app.post('/text-then-parse', async (c: any) => {
    await c.req.text()
    return c.json({ a: await c.req.parseBody() })
  })
  app.post('/blob-then-parse', async (c: any) => {
    await c.req.blob()
    return c.json({ a: await c.req.parseBody() })
  })
  app.post('/ab-then-parse', async (c: any) => {
    await c.req.arrayBuffer()
    return c.json({ a: await c.req.parseBody() })
  })
  app.post(
    '/validator-then-parse',
    validator('form', (v: unknown) => v),
    async (c: any) => c.json({ valid: c.req.valid('form'), parsed: await c.req.parseBody() })
  )
  app.post(
    '/fd-then-validator',
    async (c: any, next: any) => {
      await c.req.formData()
      await next()
    },
    validator('form', (v: unknown) => v),
    async (c: any) => c.json({ valid: c.req.valid('form') })
  )
  app.post(
    '/parse-then-validator',
    async (c: any, next: any) => {
      await c.req.parseBody()
      await next()
    },
    validator('form', (v: unknown) => v),
    async (c: any) => c.json({ valid: c.req.valid('form') })
  )
  for (const path of [
    '/fd-then-parse',
    '/parse-twice',
    '/parse-then-fd',
    '/text-then-parse',
    '/blob-then-parse',
    '/ab-then-parse',
    '/validator-then-parse',
    '/fd-then-validator',
    '/parse-then-validator',
  ]) {
    await safe(`multipart ${path}`, async () => {
      const res = await app.request(path, mkMultipart())
      return { status: res.status, body: await res.json() }
    })
    await safe(`urlenc ${path}`, async () => {
      const res = await app.request(path, mkUrlenc())
      return { status: res.status, body: await res.json() }
    })
  }
  // raw Request cases
  await safe('raw malformed multipart', async () =>
    parseBody(
      new Request('http://localhost/', {
        method: 'POST',
        body: 'not multipart',
        headers: { 'Content-Type': 'multipart/form-data; boundary=xyz' },
      })
    )
  )
  await safe('raw multipart no boundary', async () =>
    parseBody(
      new Request('http://localhost/', {
        method: 'POST',
        body: 'a=b',
        headers: { 'Content-Type': 'multipart/form-data' },
      })
    )
  )
  await safe('raw startsWith variant', async () =>
    parseBody(
      new Request('http://localhost/', {
        method: 'POST',
        body: 'a=b',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded-foo' },
      })
    )
  )
  await safe('raw mixed-case urlenc', async () =>
    parseBody(
      new Request('http://localhost/', {
        method: 'POST',
        body: 'a=b',
        headers: { 'Content-Type': 'Application/X-WWW-Form-Urlencoded; Charset=UTF-8' },
      })
    )
  )
  await safe('raw mixed-case multipart native formData (no hono)', async () => {
    const fd = new FormData()
    fd.append('foo', 'bar')
    const src = new Request('http://localhost/', { method: 'POST', body: fd })
    const ct = src.headers.get('Content-Type')!.replace('multipart/form-data', 'Multipart/Form-Data')
    const r = new Request('http://localhost/', {
      method: 'POST',
      body: await src.arrayBuffer(),
      headers: { 'Content-Type': ct },
    })
    return Object.fromEntries((await r.formData()).entries())
  })
  await safe('raw body already used', async () => {
    const r = new Request('http://localhost/', {
      method: 'POST',
      body: 'a=b',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    })
    await r.text()
    return parseBody(r)
  })
  console.log('=== ' + label + ' ===')
  console.log(JSON.stringify(out, null, 1))
}

